4. ParkingLevel ClassThe Level class represents a level in the parking lot. It manages a collection of parking spots and provides methods to park and remove vehicles.
            C++

    #include <vector>
#include "ParkingSpot.h"
#include "Vehicle.h"

class Level {
private:
    int levelNumber;
    std::vector<ParkingSpot> spots;

public:
    Level(int levelNumber, int numSpots) : levelNumber(levelNumber), spots(numSpots) {}

    bool parkVehicle(Vehicle vehicle) {
        for (ParkingSpot& spot : spots) {
            if (spot.canFitVehicle(vehicle)) {
                spot.parkVehicle(vehicle);
                return true;
            }
        }
        return false;
    }

    bool removeVehicle(Vehicle vehicle) {
        for (ParkingSpot& spot : spots) {
            if (spot.isOccupied() && spot.getVehicle() == vehicle) {
                spot.removeVehicle();
                return true;
            }
        }
        return false;
    }
};


