5. ParkingLot ClassThe ParkingLot class represents the entire parking lot. It manages multiple levels and provides methods to park and remove vehicles from the parking lot.
            C++

    #include <iostream>
#include <vector>

class Vehicle {};

class Level {
    int levelNumber;
    std::vector<Vehicle*> spots;
public:
    Level(int level, int numSpots) : levelNumber(level), spots(numSpots) {}
    bool parkVehicle(Vehicle* vehicle) {
        for (auto& spot : spots) {
            if (!spot) {
                spot = vehicle;
                return true;
            }
        }
        return false;
    }
    bool removeVehicle(Vehicle* vehicle) {
        for (auto& spot : spots) {
            if (spot == vehicle) {
                spot = nullptr;
                return true;
            }
        }
        return false;
    }
};

class ParkingLot {
    std::vector<Level> levels;
public:
    ParkingLot(int numLevels, int numSpotsPerLevel) {
        levels.resize(numLevels);
        for (int i = 0; i < numLevels; i++) {
            levels[i] = Level(i, numSpotsPerLevel);
        }
    }
    bool parkVehicle(Vehicle* vehicle) {
        for (auto& level : levels) {
            if (level.parkVehicle(vehicle)) {
                return true;
            }
        }
        return false;
    }
    bool removeVehicle(Vehicle* vehicle) {
        for (auto& level : levels) {
            if (level.removeVehicle(vehicle)) {
                return true;
            }
        }
        return false;
    }
};


